type Order struct {
    id       OrderID       // unexported: callers cannot build one directly
    customer CustomerID
}

func NewOrder(raw RawOrder) (*Order, error) {
    if raw.CustomerID == "" {
        return nil, errors.New("order: customer required")
    }
    return &Order{id: NewOrderID(), customer: CustomerID(raw.CustomerID)}, nil
}
